package com.nuclyon.technicallycoded.inventoryrollback.customdata;

import com.nuclyon.technicallycoded.inventoryrollback.InventoryRollbackPlus;
import org.bukkit.NamespacedKey;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.persistence.PersistentDataType;
import org.jetbrains.annotations.NotNull;

public class ModernPdcItemEditor implements CustomDataItemEditor {

    private final ItemStack item;

    public ModernPdcItemEditor(ItemStack item) {
        this.item = item;
    }

    @Override
    public boolean hasUUID() {
        String uuid = getString("uuid");
        return (uuid != null && !uuid.isEmpty());
    }

    @Override
    public ItemStack setString(String key, String data) {
        setData(key, PersistentDataType.STRING, data);
        return item;
    }

    @Override
    public ItemStack setInt(String key, Integer data) {
        setData(key, PersistentDataType.INTEGER, data);
        return item;
    }

    @Override
    public ItemStack setLong(String key, Long data) {
        setData(key, PersistentDataType.LONG, data);
        return item;
    }

    @Override
    public ItemStack setDouble(String key, Double data) {
        setData(key, PersistentDataType.DOUBLE, data);
        return item;
    }

    @Override
    public ItemStack setFloat(String key, Float data) {
        setData(key, PersistentDataType.FLOAT, data);
        return item;
    }

    @Override
    public String getString(String key) {
        return getData(key, PersistentDataType.STRING);
    }

    @Override
    public int getInt(String key) {
        return getData(key, PersistentDataType.INTEGER);
    }

    @Override
    public Long getLong(String key) {
        return getData(key, PersistentDataType.LONG);
    }

    @Override
    public double getDouble(String key) {
        return getData(key, PersistentDataType.DOUBLE);
    }

    @Override
    public Float getFloat(String key) {
        return getData(key, PersistentDataType.FLOAT);
    }

    @Override
    public ItemStack setItemData() {
        return item;
    }

    private <T> T getData(String key, PersistentDataType<T, T> type) {
        if (item == null) return null;

        ItemMeta itemMeta = item.getItemMeta();
        PersistentDataContainer pdc = itemMeta.getPersistentDataContainer();

        NamespacedKey namedKey = getNamespacedKey(key);

        if (!pdc.has(namedKey, type)) return null;
        return pdc.get(namedKey, type);
    }

    private <T> void setData(String key, PersistentDataType<T, T> type, T data) {
        if (item == null) return;

        ItemMeta itemMeta = item.getItemMeta();
        PersistentDataContainer pdc = itemMeta.getPersistentDataContainer();
        pdc.set(getNamespacedKey(key), type, data);

        item.setItemMeta(itemMeta);
    }

    private static @NotNull NamespacedKey getNamespacedKey(String key) {
        return new NamespacedKey(InventoryRollbackPlus.getInstance(), key);
    }

}

package com.nuclyon.technicallycoded.inventoryrollback.util;

import com.nuclyon.technicallycoded.inventoryrollback.InventoryRollbackPlus;
import me.danjono.inventoryrollback.config.ConfigData;
import me.danjono.inventoryrollback.config.MessageData;
import me.danjono.inventoryrollback.data.LogType;
import me.danjono.inventoryrollback.data.PlayerData;
import me.danjono.inventoryrollback.inventory.RestoreInventory;
import org.apache.commons.lang3.Validate;
import org.bukkit.Bukkit;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.InvalidConfigurationException;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.inventory.ItemStack;
import org.jetbrains.annotations.NotNull;

import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.*;
import java.util.logging.Logger;

public class LegacyBackupConversionUtil {

    public static Map<String, LogType> oldLogTypesMap = new HashMap<>();

    static {
        oldLogTypesMap.put("WORLDCHANGE", LogType.WORLD_CHANGE);
    }

    public static void convertOldBackupData() {
        Logger logger = InventoryRollbackPlus.getPluginLogger();

        List<File> oldBackupTypeFolders = new ArrayList<>();

        File oldBackupsRoot = new File(ConfigData.getFolderLocation().getParentFile(), "InventoryRollback/saves");

        oldBackupTypeFolders.add(new File(oldBackupsRoot, "deaths"));
        oldBackupTypeFolders.add(new File(oldBackupsRoot, "joins"));
        oldBackupTypeFolders.add(new File(oldBackupsRoot, "quits"));
        oldBackupTypeFolders.add(new File(oldBackupsRoot, "worldChanges"));
        oldBackupTypeFolders.add(new File(oldBackupsRoot, "force"));

        int logTypeNumber = -1;
        List<LogType> logTypes = new ArrayList<>();
        logTypes.add(LogType.DEATH);
        logTypes.add(LogType.JOIN);
        logTypes.add(LogType.QUIT);
        logTypes.add(LogType.WORLD_CHANGE);
        logTypes.add(LogType.FORCE);

        for (File oldBackupFolder : oldBackupTypeFolders) {

            logTypeNumber++;

            if (!oldBackupFolder.exists()) {
                logger.warning(MessageData.getPluginPrefix() + "Backup folder does not exist at " + oldBackupFolder.getAbsolutePath() + "! Skipping...");
                continue;
            }

            // Add all YAML files to list
            File[] availableFiles = oldBackupFolder.listFiles();
            if (availableFiles == null) continue;

            List<File> backupFilesToConvert = getFilesToConvert(availableFiles);

            LogType currLogTypeProcessing = logTypes.get(logTypeNumber);
            logger.info(MessageData.getPluginPrefix() + "Converting the backup location " + currLogTypeProcessing.name());

            for (File backupFile : backupFilesToConvert) {
                convertBackupFile(logger, backupFile, currLogTypeProcessing);
            }

        }

        InventoryRollbackPlus.getPluginLogger().info(MessageData.getPluginPrefix() + "Conversion completed!");
    }

    private static ArrayList<File> getFilesToConvert(File[] availableFiles) {
        ArrayList<File> backupFiles = new ArrayList<>();

        // Sanity check files in the folder & add them to a list to process later
        for (File file : availableFiles) {
            String originalFileName = file.getName();
            String[] fileParts = originalFileName.split("\\.");
            String fileUUIDStr = fileParts[0];
            String fileExtension = fileParts[1];

            UUID playerUuid;
            try {
                // Check if it's a valid UUID
                playerUuid = UUID.fromString(fileUUIDStr);
            } catch (IllegalArgumentException ex) {
                InventoryRollbackPlus.getInstance().getLogger().severe(
                        "An error occurred when trying to retrieve a old backup player UUID! " +
                                "Please seek help in the issues section of the InventryRollbackPlus github page.");
                ex.printStackTrace();
                continue;
            }

            if (file.isFile() && fileExtension.equals("yml")) {
                backupFiles.add(file);
            }
        }

        return backupFiles;
    }

    public static void convertBackupFile(Logger logger, File backupFile, LogType logTypeProcessing) {
        YamlConfiguration oldBackupDataConfig;
        oldBackupDataConfig = loadConfiguration(backupFile);

        if (oldBackupDataConfig == null) {
            logger.warning(MessageData.getPluginPrefix() + "Error converting backup file at " +
                    backupFile.getAbsolutePath() + " - Invalid YAML format possibly from corruption.");
            return;
        }

        ConfigurationSection configSectionData = oldBackupDataConfig.getConfigurationSection("data");
        if (configSectionData == null) {
            return;
        }
        Set<String> timestamps = configSectionData.getKeys(false);

        for (String timestampStr : timestamps) {
            try {
                Long timestamp = Long.parseLong(timestampStr);
                String fileName = backupFile.getName();
                String fileUUIDStr = fileName.substring(0, fileName.indexOf('.'));

                UUID uuid;
                try {
                    // Check if it's a valid UUID
                    uuid = UUID.fromString(fileUUIDStr);
                } catch (IllegalArgumentException ex) {
                    InventoryRollbackPlus.getInstance().getLogger().severe(
                            "An error occurred when trying to retrieve the player UUID from " + backupFile.getAbsolutePath() + "#" + timestampStr + "! " +
                                    "Please ask for help in the issues section of the InventoryRollbackPlus github page.");
                    ex.printStackTrace();
                    continue;
                }

                // ---- Load all data from the old config ----

                String packageVersion = oldBackupDataConfig.getString("data." + timestamp + ".version");
                ItemStack[] mainInvItems = RestoreInventory.getInventoryItems(packageVersion,
                        oldBackupDataConfig.getString("data." + timestamp + ".inventory"));
                ItemStack[] armorItems = RestoreInventory.getInventoryItems(packageVersion,
                        oldBackupDataConfig.getString("data." + timestamp + ".armour"));
                ItemStack[] enderChestItems = RestoreInventory.getInventoryItems(packageVersion,
                        oldBackupDataConfig.getString("data." + timestamp + ".enderchest"));
                float xp = Float.parseFloat(
                        oldBackupDataConfig.getString("data." + timestamp + ".xp"));
                double health = oldBackupDataConfig.getDouble("data." + timestamp + ".health");
                int foodLevel = oldBackupDataConfig.getInt("data." + timestamp + ".hunger");
                float saturation = Float.parseFloat(
                        oldBackupDataConfig.getString("data." + timestamp + ".saturation"));
                String worldName = oldBackupDataConfig.getString("data." + timestamp + ".location.world");
                double posX = oldBackupDataConfig.getDouble("data." + timestamp + ".location.x");
                double posY = oldBackupDataConfig.getDouble("data." + timestamp + ".location.y");
                double posZ = oldBackupDataConfig.getDouble("data." + timestamp + ".location.z");
                String logTypeStoredString = oldBackupDataConfig.getString("data." + timestamp + ".logType");
                String deathReason = oldBackupDataConfig.getString("data." + timestamp + ".deathReason");

                // ---- Process all loaded data ----

                PlayerData importedData = new PlayerData(uuid, logTypeProcessing, timestamp);

                importedData.setMainInventory(mainInvItems);
                importedData.setArmour(armorItems);
                importedData.setEnderChest(enderChestItems);
                importedData.setXP(xp);
                importedData.setHealth(health);
                importedData.setFoodLevel(foodLevel);
                importedData.setSaturation(saturation);
                importedData.setWorld(worldName);
                importedData.setX(posX);
                importedData.setY(posY);
                importedData.setZ(posZ);

                // Sanity check log type
                if (logTypeStoredString == null) {
                    InventoryRollbackPlus.getInstance().getLogger().severe(
                            "An error occurred when trying to retrieve the backup type of " + backupFile.getAbsolutePath() + "#" + timestampStr + "! " +
                                    "Please ask for help in the issues section of the InventoryRollbackPlus github page. (typeStr is null)");
                    continue;
                }

                // Convert old log type format to new enum value
                LogType logTypeStored = oldLogTypesMap.get(logTypeStoredString);

                // If this log type isn't an old type, attempt retrieval from newer LogType enum
                if (logTypeStored == null) {
                    try {
                        logTypeStored = LogType.valueOf(logTypeStoredString);
                    } catch (IllegalArgumentException ex) {
                        InventoryRollbackPlus.getInstance().getLogger().severe(
                                "An error occurred when trying to retrieve the backup type of " + backupFile.getAbsolutePath() + "#" + timestampStr + "! " +
                                        "Please ask for help in the issues section of the InventoryRollbackPlus github page. (typeStr: " + logTypeStoredString + ")");
                        continue;
                    }
                }

                // Apply last data after sanity checks & conversions
                importedData.setLogType(logTypeStored);
                importedData.setVersion(packageVersion);
                if (deathReason != null) importedData.setDeathReason(deathReason);

                // Save the data to the new folder location
                importedData.saveData(true);
            } catch (Exception e) {
                InventoryRollbackPlus.getPluginLogger().warning(
                        MessageData.getPluginPrefix() + "Error converting backup file at " +
                                backupFile.getAbsolutePath() + " on timestamp " + timestampStr);
            }
        }
    }

    public static YamlConfiguration loadConfiguration(@NotNull File file) {
        Validate.notNull(file, "File cannot be null");
        YamlConfiguration config;

        try {
            config = new YamlConfiguration();
            config.load(file);
        } catch (FileNotFoundException ignored) {
            return null;
        } catch (IOException | InvalidConfigurationException var4) {
            Bukkit.getLogger().severe("Cannot load " + file);
            return null;
        }

        return config;
    }

}

package me.danjono.inventoryrollback.gui.menu;

import com.nuclyon.technicallycoded.inventoryrollback.InventoryRollbackPlus;
import com.nuclyon.technicallycoded.inventoryrollback.folia.FoliaRunnable;
import com.nuclyon.technicallycoded.inventoryrollback.folia.SchedulerUtils;
import com.tcoded.lightlibs.bukkitversion.MCVersion;
import me.danjono.inventoryrollback.config.ConfigData;
import me.danjono.inventoryrollback.config.MessageData;
import me.danjono.inventoryrollback.data.LogType;
import me.danjono.inventoryrollback.data.PlayerData;
import me.danjono.inventoryrollback.gui.Buttons;
import me.danjono.inventoryrollback.gui.InventoryName;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemStack;

import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;

public class MainInventoryBackupMenu {

    public static final int GIVE_SHULKERS_BUTTON_SLOT = 47;
	private final InventoryRollbackPlus main;

	private final Player staff;
	private final UUID playerUUID;
	private final LogType logType;
	private final Long timestamp;
	private final ItemStack[] mainInventory;
	private final ItemStack[] armor;
	private final ItemStack[] enderChest;
	private final String location;
	private final double health;
	private final int hunger;
	private final float saturation;
	private final float xp;

    private final Buttons buttons;
    private Inventory inventory;

	private int mainInvLen;

	public MainInventoryBackupMenu(Player staff, PlayerData data, String location) {
		this.main = InventoryRollbackPlus.getInstance();

		this.staff = staff;
		this.playerUUID = data.getOfflinePlayer().getUniqueId();
		this.logType = data.getLogType();
		this.timestamp = data.getTimestamp();
		this.mainInventory = data.getMainInventory();
		this.armor = data.getArmour();
	    this.enderChest = data.getEnderChest();
		this.location = location;
		this.health = data.getHealth();
		this.hunger = data.getFoodLevel();
		this.saturation = data.getSaturation();
		this.xp = data.getXP();

		this.buttons = new Buttons(playerUUID);

		this.mainInvLen = mainInventory == null ? 0 : mainInventory.length;

		createInventory();
	}

	public void createInventory() {
	    inventory = Bukkit.createInventory(staff, InventoryName.MAIN_BACKUP.getSize(), InventoryName.MAIN_BACKUP.getName());

	    //Add back button
        inventory.setItem(45, buttons.inventoryMenuBackButton(MessageData.getBackButton(), logType, timestamp));

		// Add get shulker button
		if (main.getVersion().greaterOrEqThan(MCVersion.v1_11.toBukkitVersion()))
			inventory.setItem(GIVE_SHULKERS_BUTTON_SLOT, buttons.giveShulkerBox(logType, timestamp));

		// Add restore all player inventory button
		if (ConfigData.isRestoreToPlayerButton())
			inventory.setItem(48, buttons.restoreAllInventory(logType, timestamp));
		else
			inventory.setItem(48, buttons.restoreAllInventoryDisabled(logType, timestamp));

		//Add teleport back button
		inventory.setItem(49, buttons.enderPearlButton(logType, location));

		//Add Enderchest icon
		inventory.setItem(50, buttons.enderChestButton(logType, timestamp, enderChest));

		//Add health icon
		inventory.setItem(51, buttons.healthButton(logType, health));

		//Add hunger icon
		inventory.setItem(52, buttons.hungerButton(logType, hunger, saturation));

		//Add Experience Bottle
		inventory.setItem(53, buttons.experiencePotion(logType, xp));
	}

	public Inventory getInventory() {
	    return this.inventory;
	}

	public void showBackupItems() {
		// Make sure we are not running this on the main thread
		assert !Bukkit.isPrimaryThread();

		int item = 0;
		AtomicInteger position = new AtomicInteger();

		//If the backup file is invalid it will return null, we want to catch it here
		try {
    		// Add items, 5 per tick
			SchedulerUtils.runTaskTimer(null, new FoliaRunnable() {

				boolean processedHotbar;
				int menuPos = 27;
				int backupPos = 0;
				final int max = Math.min(mainInvLen, 36); // excluded

				@Override
				public void run() {
					for (int i = 0; i < 6; i++) {
						// If hit max item position, stop
						if (backupPos >= max) {
							this.cancel();
							return;
						}

						ItemStack itemStack = mainInventory[backupPos];
						if (itemStack != null) {
							inventory.setItem(menuPos, itemStack);
						}

						// Move to next menu slot
						menuPos++;
						// We were incrementing the hotbar position (bottom of the UI) first. Once we reach that
						// slot, we move back to the top of the UI for the rest of the inventory
						if (menuPos >= 36 && !processedHotbar) {
							menuPos = 0;
						}

						// Move to next item stack
						backupPos++;
					}
				}
			}, 1, 1);
		} catch (Exception ex) {
			ex.printStackTrace();
			staff.sendMessage(MessageData.getPluginPrefix() + MessageData.getErrorInventory());
		    return;
		}

		item = 36;
		position.set(44);

		//Add armor
		if (armor != null && armor.length > 0) {
            for (int i = 0; i < armor.length; i++) {
                // Place item safely
                final int finalPos = position.getAndDecrement();
                final int finalItem = i;
                SchedulerUtils.callSyncMethod(null, () -> {
                    inventory.setItem(finalPos, armor[finalItem]);
                    return null;
                }).whenComplete((res, ex) -> {
                    if (ex != null) ex.printStackTrace();
                });
            }
		} else {
            for (; item < mainInvLen; item++) {
                if (mainInventory[item] != null) {
                    // Place item safely
                    final int finalPos = position.getAndDecrement();
                    final int finalItem = item;
                    SchedulerUtils.callSyncMethod(null, () -> {
                        inventory.setItem(finalPos, mainInventory[finalItem]);
                        return null;
                    }).whenComplete((res, ex) -> {
                        if (ex != null) ex.printStackTrace();
                    });
                } else {
                    position.getAndDecrement();
                }
            }
		}
	}

}

package me.danjono.inventoryrollback.gui.menu;

import com.nuclyon.technicallycoded.inventoryrollback.InventoryRollbackPlus;
import com.nuclyon.technicallycoded.inventoryrollback.folia.FoliaRunnable;
import com.nuclyon.technicallycoded.inventoryrollback.folia.SchedulerUtils;
import com.tcoded.lightlibs.bukkitversion.MCVersion;
import me.danjono.inventoryrollback.config.ConfigData;
import me.danjono.inventoryrollback.config.MessageData;
import me.danjono.inventoryrollback.data.LogType;
import me.danjono.inventoryrollback.data.PlayerData;
import me.danjono.inventoryrollback.gui.Buttons;
import me.danjono.inventoryrollback.gui.InventoryName;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemStack;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

public class EnderChestBackupMenu {

    public static final int GIVE_SHULKERS_BUTTON_SLOT = InventoryName.ENDER_CHEST_BACKUP.getSize() - 6;
    private final InventoryRollbackPlus main;
    private int pageNumber;

    private Player staff;
    private UUID playerUUID;
    private LogType logType;
    private Long timestamp;
    private ItemStack[] enderchest;

    private Buttons buttons;
    private Inventory inventory;

    public EnderChestBackupMenu(Player staff, PlayerData data, int pageNumberIn) {
        this.main = InventoryRollbackPlus.getInstance();

        this.staff = staff;
        this.playerUUID = data.getOfflinePlayer().getUniqueId();
        this.logType = data.getLogType();
        this.timestamp = data.getTimestamp();
        this.enderchest = data.getEnderChest();
        this.pageNumber = pageNumberIn;
        this.buttons = new Buttons(playerUUID);

        createInventory();
    }

    public void createInventory() {
        inventory = Bukkit.createInventory(staff, InventoryName.ENDER_CHEST_BACKUP.getSize(), InventoryName.ENDER_CHEST_BACKUP.getName());

        List<String> lore = new ArrayList<>();
        if (pageNumber == 1) {
            ItemStack mainInventoryMenu = buttons.inventoryMenuBackButton(MessageData.getBackButton(), logType, timestamp);
            inventory.setItem(InventoryName.ENDER_CHEST_BACKUP.getSize() - 8, mainInventoryMenu);
        }

        if (pageNumber > 1) {
            lore.add("Page " + (pageNumber - 1));
            ItemStack previousPage = buttons.enderChestBackButton(MessageData.getPreviousPageButton(), logType, pageNumber - 1, timestamp, lore);

            inventory.setItem(InventoryName.ENDER_CHEST_BACKUP.getSize() - 8, previousPage);
        }
    }

    public Inventory getInventory() {
        return this.inventory;
    }

    public void showEnderChestItems() {
        //Check how many items there are in total
        if (enderchest == null) enderchest = new ItemStack[0];
        int itemsToDisplay = enderchest.length;

        // How many rows are available
        int spaceAvailable = InventoryName.ROLLBACK_LIST.getSize() - 9;

        // How many pages are required
        int pagesRequired = Math.max(1, (int) Math.ceil(itemsToDisplay / (double) spaceAvailable));

        //Check if pageNumber supplied is greater then pagesRequired, if true set to last page
        if (pageNumber > pagesRequired) {
            pageNumber = pagesRequired;
        } else if (pageNumber <= 0) {
            pageNumber = 1;
        }

        //If the backup file is invalid it will return null, we want to catch it here
        try {

            // Add items, 5 per tick
            SchedulerUtils.runTaskTimer(null, new FoliaRunnable() {

                int invPosition = 0;
                int itemPos = (pageNumber - 1) * 27;
                final int max = Math.max(0, itemPos + Math.min(enderchest.length - itemPos, 27)); // excluded but starts from 0

                @Override
                public void run() {
                    for (int i = 0; i < 6; i++) {
                        // If hit max item position, stop
                        if (itemPos >= max) {
                            this.cancel();
                            return;
                        }


                        ItemStack itemStack = enderchest[itemPos];
                        inventory.setItem(invPosition, itemStack); // setting null is fine (clears/keeps empty)
                        invPosition++;
                        itemPos++;
                    }
                }
            }, 1, 1);
        } catch (NullPointerException e) {
            staff.sendMessage(MessageData.getPluginPrefix() + MessageData.getErrorInventory());
            return;
        }

        // Add restore all player inventory button
        if (ConfigData.isRestoreToPlayerButton()) {
            inventory.setItem(
                    InventoryName.ENDER_CHEST_BACKUP.getSize() - 5,
                    buttons.restoreAllInventory(logType, timestamp));
        } else {
            inventory.setItem(
                    InventoryName.ENDER_CHEST_BACKUP.getSize() - 5,
                    buttons.restoreAllInventoryDisabled(logType, timestamp));
        }

        if (main.getVersion().greaterOrEqThan(MCVersion.v1_11.toBukkitVersion()))
            inventory.setItem(GIVE_SHULKERS_BUTTON_SLOT, buttons.giveShulkerBox(logType, timestamp));

        List<String> lore = new ArrayList<>();
        if (pageNumber < pagesRequired) {
            lore.add("Page " + (pageNumber + 1));
            ItemStack nextPage = buttons.enderChestNextButton(MessageData.getNextPageButton(), logType, pageNumber + 1, timestamp, lore);

            inventory.setItem(InventoryName.ENDER_CHEST_BACKUP.getSize() - 2, nextPage);
            lore.clear();
        }
    }

}

